# envcfg.py

import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env=os.environ):
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config[env_key] = _coerce_value(value, defaults.get(env_key))
    return config

def _coerce_value(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ('true', 'yes', '1')
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for {value}')

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'key': 'value'}
    assert load_config(defaults) == {'key': 'value'}

def test_toml_file():
    defaults = {'key': 'value'}
    toml_path = 'config.toml'
    with open(toml_path, 'w') as f:
        f.write('key = "toml_value"')
    assert load_config(defaults, toml_path) == {'key': 'toml_value'}
    os.remove(toml_path)

def test_env_variable():
    defaults = {'key': 'value'}
    os.environ['APP__KEY'] = 'env_value'
    assert load_config(defaults, env_prefix='APP__') == {'key': 'env_value'}
    del os.environ['APP__KEY']

def test_coercion():
    defaults = {'int_key': 1, 'float_key': 1.0, 'bool_key': True, 'str_key': 'string'}
    os.environ['APP__INT_KEY'] = '2'
    os.environ['APP__FLOAT_KEY'] = '2.0'
    os.environ['APP__BOOL_KEY'] = 'false'
    os.environ['APP__STR_KEY'] = 'new_string'
    assert load_config(defaults, env_prefix='APP__') == {
        'int_key': 2,
        'float_key': 2.0,
        'bool_key': False,
        'str_key': 'new_string'
    }
    for key in ('APP__INT_KEY', 'APP__FLOAT_KEY', 'APP__BOOL_KEY', 'APP__STR_KEY'):
        del os.environ[key]

def test_missing_default():
    defaults = {'key': 'value'}
    os.environ['APP__MISSING_KEY'] = 'some_value'
    with pytest.raises(ConfigError) as excinfo:
        load_config(defaults, env_prefix='APP__')
    assert 'missing_key' in str(excinfo.value)
    del os.environ['APP__MISSING_KEY']

def test_unsupported_type():
    defaults = {'key': []}
    os.environ['APP__KEY'] = 'some_value'
    with pytest.raises(ConfigError) as excinfo:
        load_config(defaults, env_prefix='APP__')
    assert 'some_value' in str(excinfo.value)
    del os.environ['APP__KEY']

